function Mapamain() {
  // Variável no React que armazenará as informações da feira clicada
  const [feiraSelecionada, setFeiraSelecionada] = useState(null);
  const [busca, setBusca] = useState('');

  // Filtragem básica para a busca
  const feirasFiltradas = FEIRAS_DADOS.filter(feira =>
    feira.nome.toLowerCase().includes(busca.toLowerCase()) ||
    feira.endereco.toLowerCase().includes(busca.toLowerCase())
  );

  return (
    // INSIRA SUA CHAVE DA API DO GOOGLE MAPS AQUI
    <APIProvider apiKey="SUA_CHAVE_API_DO_GOOGLE_AQUI">
      <section className={Styles.mapaMain}>
        
        {/* Renderização do Mapa React do Google */}
        <div className={Styles.mapaIframe}>
          <Map
            defaultCenter={{ lat: -23.55052, lng: -46.633308 }}
            defaultZoom={13}
            mapId="SEU_MAP_ID_AQUI" // Necessário para usar AdvancedMarker
            gestureHandling={'greedy'}
            disableDefaultUI={false}
          >
            {feirasFiltradas.map((feira) => (
              <AdvancedMarker
                key={feira.id}
                position={{ lat: feira.lat, lng: feira.lng }}
                // EVENTO DE CLIQUE: Guarda as infos da feira no estado React
                onClick={() => setFeiraSelecionada(feira)}
              >
                <Pin background={'#22c55e'} glyphColor={'#fff'} borderColor={'#15803d'} />
              </AdvancedMarker>
            ))}
          </Map>
        </div>

        {/* Painel Lateral que consome a variável React */}
        <aside className={Styles.cardLateral}>
          <div className={Styles.cardTitle}>
            <img src={Logo} alt="Logo" style={{ width: '40px', marginBottom: '10px' }} />
            <h1>Encontre a feira mais próxima de você</h1>
          </div>

          <div className={Styles.fundoSection}>
            <div className={Styles.search}>
              
              <input
                type="text"
                placeholder="Digite o nome ou bairro..."
                value={busca}
                onChange={(e) => setBusca(e.target.value)}
                style={{
                  width: '100%',
                  padding: '8px',
                  borderRadius: '6px',
                  border: '1px solid #ccc',
                  marginTop: '5px'
                }}
              />
            </div>

            {/* AQUI EXIBIMOS A FEIRA SELECIONADA */}
            <div style={{ marginTop: '20px', padding: '10px', background: '#fff', borderRadius: '8px' }}>
              {feiraSelecionada ? (
                <div>
                  <h2 style={{ color: '#22c55e', fontSize: '1.2rem' }}>{feiraSelecionada.nome}</h2>
                  <p><strong>Endereço:</strong> {feiraSelecionada.endereco}</p>
                  <p><strong>Horário:</strong> {feiraSelecionada.horario}</p>
                  
                  <button 
                    onClick={() => setFeiraSelecionada(null)}
                    style={{ marginTop: '10px', cursor: 'pointer' }}
                  >
                    Limpar Seleção
                  </button>
                </div>
              ) : (
                <p style={{ color: '#666' }}>Clique em uma feira no mapa para ver detalhes aqui.</p>
              )}
            </div>

          </div>
        </aside>
      </section>
    </APIProvider>
  );
}

export default Mapamain;